python3 -c "
import json
path='research/jev-bounded-judgment/phase1/followup-05-cross-family/staging/big-pickle/results/scored.ndjson'
gm={}
jev={}
with open(path) as f:
    for line in f:
        o=json.loads(line)
        if not o['answerable']: continue
        if o['mechanism']=='general_model': gm[o['case_id']]=o['correct']
        elif o['mechanism']=='jev': jev[o['case_id']]=o['correct']
print('gm n', len(gm), 'jev n', len(jev), 'shared', len(set(gm)&set(jev)))
b=c=ties=0
for cid in sorted(set(gm)&set(jev)):
    g=gm[cid]; j=jev[cid]
    if g is True and j is False: b+=1; print('b', cid)
    elif j is True and g is False: c+=1; print('c', cid)
    else: ties+=1
print(f'b={b} c={c} ties={ties}')
# also list disagreements in correctness
for cid in sorted(set(gm)&set(jev)):
    if gm[cid]!=jev[cid]: print('disagree correctness', cid, 'gm', gm[cid], 'jev', jev[cid])
# list gm incorrect
print('gm incorrect:', [cid for cid,v in gm.items() if v is False])
print('jev incorrect:', [cid for cid,v in jev.items() if v is False])
"

